//! W4-RT-HEX, ruling C7: the hexagonal lattice against OpenMC 0.16.0.
//!
//! `tests/fixtures/openmc_hex/{hex_x,hex_y}/oracle.json` (generated by `gen_hex.py`, committed with
//! the OpenMC deck) hold, for a 3-ring `openmc.HexLattice` of 19 pins (one universe, radius and cell
//! ids per element, centre off the origin), OpenMC's `find_cell` at 1200 points per orientation (the few within twice the model resolution of a face are skipped) and
//! OpenMC's own lattice path of every element. The sm-rt world must give the same element and the
//! same region at every point after the index map written in `DESIGN.md`:
//!
//! * OpenMC orientation `x` is `LatticeKind::Hex`, `y` is `LatticeKind::HexYRows`;
//! * the path indices `(a, b)` of an element are centred axial coordinates: the element centre is
//!   `center + pitch (a + b/2, sqrt(3)/2 b)` (`x`) or `center + pitch (sqrt(3)/2 a, b + a/2)` (`y`),
//!   which is sm-rt's `(q, r) = (a, b)`; the sm-rt array is the 5 x 5 rhombus `(i, j) = (a + 2, b + 2)`
//!   with element `(0, 0)` at `center + c(-2, -2)`; the six rhombus corners outside the 3 rings are
//!   pad elements (OpenMC's `outer` universe, cell 900, covers them).
//!
//! The wrong pairing (kind and orientation exchanged) fails many points: the test counts them.
#[path = "common/csg.rs"]
mod csg;
#[path = "common/hex.rs"]
mod hex;

use csg::*;
use serde_json::Value;
use sm_core::Point3;
use sm_rt::{MeshTrackerBuilder, WorldTracker};
use sm_rt_api::{BoundarySpec, BuildInput, BuildOptions, ComponentId, ComponentKind, CsgLeafInput, HierInput, InstancePolicy, Lattice, LatticeKind, LeafInput, Scratch, Tracker, WorldSpec};

fn oracle(name: &str) -> Value {
    let p = format!("{}/tests/fixtures/openmc_hex/{name}/oracle.json", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(&std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{p}: {e}"))).unwrap()
}

fn f(v: &Value) -> f64 {
    v.as_f64().unwrap()
}

/// The world of the oracle's lattice with the given sm-rt kind.
fn world(o: &Value, kind_x: bool) -> WorldTracker {
    let (pitch, n) = (f(&o["pitch"]), o["n_rings"].as_i64().unwrap() as i32);
    let (c, zh) = (o["center"].as_array().unwrap(), f(&o["zhalf"]));
    let side = 2 * n - 1;
    let elements = o["elements"].as_array().unwrap();
    let kind = if kind_x { LatticeKind::Hex { pitch, z_pitch: 2.0 * zh } } else { LatticeKind::HexYRows { pitch, z_pitch: 2.0 * zh } };
    // Element (0, 0) of the rhombus is OpenMC's (-(n-1), -(n-1)): origin = center + c(-(n-1), -(n-1)).
    let probe = Lattice::new(kind, p3(0.0, 0.0, 0.0), [1, 1, 1], vec![ComponentId(0)], None);
    let c00 = probe.element_center([-(n - 1), -(n - 1), 0]);
    let origin = p3(f(&c[0]) + c00.x, f(&c[1]) + c00.y, 0.0);
    // Leaves: one per OpenMC element (radius of its universe), then the pad.
    let mut leaves: Vec<Fx> = elements.iter().map(|e| hex::hex_pin(kind_x, pitch, f(&e["radius"]), zh, &format!("u{}", e["universe"]))).collect();
    leaves.push(hex::hex_pin(kind_x, pitch, 0.3, zh, "pad"));
    let pad = elements.len() as u32;
    let mut fills = vec![ComponentId(pad); (side * side) as usize];
    for (k, e) in elements.iter().enumerate() {
        let (i, j) = (e["q"].as_i64().unwrap() as i32 + n - 1, e["r"].as_i64().unwrap() as i32 + n - 1);
        fills[(i + side * j) as usize] = ComponentId(k as u32);
    }
    let mut comps: Vec<ComponentKind> = (0..leaves.len()).map(|k| ComponentKind::Leaf { input: k }).collect();
    comps.push(ComponentKind::Lattice(Lattice::new(kind, origin, [side as u32, side as u32, 1], fills, None)));
    let spec = WorldSpec::new(comps, ComponentId(leaves.len() as u32), InstancePolicy::Auto);
    let bnd = BoundarySpec::default();
    let ins: Vec<LeafInput<'_>> = leaves.iter().map(|l| LeafInput::Csg(CsgLeafInput::new(&l.store, &l.cells, l.bounds, &l.complement))).collect();
    let h = HierInput::new(&spec, &ins, &bnd);
    MeshTrackerBuilder.build_world(&BuildInput::Hier(h), &BuildOptions::default()).expect("world").0
}

/// Mismatches against the oracle (of `points` compared) for a kind; `Err` names the first.
fn compare(o: &Value, w: &WorldTracker, x_rows: bool) -> (usize, usize, Option<String>) {
    let (n, side) = (o["n_rings"].as_i64().unwrap() as i32, 2 * o["n_rings"].as_i64().unwrap() as i32 - 1);
    let elements = o["elements"].as_array().unwrap();
    let outer = o["outer_cell"].as_i64().unwrap();
    // (i + side j) -> OpenMC element, for the real elements.
    let mut by_lin = std::collections::BTreeMap::new();
    for e in elements {
        let (i, j) = (e["q"].as_i64().unwrap() as i32 + n - 1, e["r"].as_i64().unwrap() as i32 + n - 1);
        by_lin.insert((i + side * j) as i64, e);
    }
    let mut sc = Scratch::new();
    let (mut bad, mut total, mut first) = (0, 0, None);
    // Hexagon faces of every element, from the oracle's own centres: a point within twice the
    // model resolution of a face is on it for sm-rt (the direction decides) and is not compared.
    let (pitch, c0) = (f(&o["pitch"]), o["center"].as_array().unwrap());
    let kind = if x_rows { LatticeKind::Hex { pitch, z_pitch: 1.0 } } else { LatticeKind::HexYRows { pitch, z_pitch: 1.0 } };
    let probe = Lattice::new(kind, p3(f(&c0[0]), f(&c0[1]), 0.0), [1, 1, 1], vec![ComponentId(0)], None);
    let tol = w.info().tol.linear;
    let near_face = |q: Point3| {
        (-(n - 1)..n).any(|a| {
            (-(n - 1)..n).any(|b| {
                let c = probe.element_center([a, b, 0]);
                let sd = hex::flats(x_rows).iter().map(|f| ((q.x - c.x) * f[0] + (q.y - c.y) * f[1]).abs()).fold(0.0, f64::max) - 0.5 * pitch;
                sd.abs() < 2.0 * tol
            })
        })
    };
    let mut skipped = 0;
    for pt in o["points"].as_array().unwrap() {
        let p = pt["p"].as_array().unwrap();
        let q = Point3::new(f(&p[0]), f(&p[1]), f(&p[2]));
        let omc = pt["cell"].as_i64().unwrap();
        if near_face(q) {
            skipped += 1;
            continue;
        }
        let loc = w.locate(q, None, None, &mut sc).unwrap();
        total += 1;
        let ok = if omc == outer {
            // Outside the 19 elements: a pad element or nothing, never a real element.
            loc.cell.is_none() || !by_lin.contains_key(&i64::from(loc.cell.0 / 2))
        } else {
            let (u, fuel) = ((omc - 100) / 10, omc % 10 == 0);
            let e = elements.iter().find(|e| e["universe"].as_i64() == Some(u)).unwrap();
            let lin = (e["q"].as_i64().unwrap() + i64::from(n) - 1) + i64::from(side) * (e["r"].as_i64().unwrap() + i64::from(n) - 1);
            !loc.cell.is_none() && i64::from(loc.cell.0) == 2 * lin + i64::from(!fuel)
        };
        if !ok {
            bad += 1;
            first.get_or_insert_with(|| format!("{:?} kind {} openmc cell {omc} -> cell {:?}", q, pt["kind"], loc.cell));
        }
    }
    assert!(skipped <= 10, "{skipped} points on a face");
    (bad, total, first)
}

#[test]
fn the_hex_world_equals_openmc_find_cell_for_both_orientations() {
    for (name, x_rows) in [("hex_x", true), ("hex_y", false)] {
        let o = oracle(name);
        assert_eq!(o["openmc_version"], "0.16.0");
        assert_eq!(o["orientation"], if x_rows { "x" } else { "y" });
        let (bad, total, first) = compare(&o, &world(&o, x_rows), x_rows);
        assert!(total >= 1190);
        assert_eq!(bad, 0, "{name}: {bad} of {total} points differ; first {first:?}");
        // The exchanged pairing is observably wrong: the index map and the orientation are pinned.
        let (bad_other, _, _) = compare(&o, &world(&o, !x_rows), !x_rows);
        assert!(bad_other > 200, "{name}: the wrong lattice kind still matches {} of {total} points", total - bad_other);
    }
}

#[test]
fn the_oracle_records_the_index_map() {
    // OpenMC's own paths: every (q, r) is distinct and inside 3 rings; the ring order starts at
    // the right (x) or the top (y) and runs clockwise: element k of ring 0 is `k` steps from it.
    for name in ["hex_x", "hex_y"] {
        let o = oracle(name);
        let els = o["elements"].as_array().unwrap();
        assert_eq!(els.len(), 19);
        let qr: std::collections::BTreeSet<(i64, i64)> = els.iter().map(|e| (e["q"].as_i64().unwrap(), e["r"].as_i64().unwrap())).collect();
        assert_eq!(qr.len(), 19);
        for &(q, r) in &qr {
            assert!(q.abs().max(r.abs()).max((q + r).abs()) <= 2, "{name}: ({q}, {r}) outside 3 rings");
        }
        let first = (els[0]["q"].as_i64().unwrap(), els[0]["r"].as_i64().unwrap());
        assert_eq!(first, if name == "hex_x" { (2, 0) } else { (0, 2) }, "{name}");
        // The centre universe is the origin element.
        assert_eq!((els[18]["q"].as_i64(), els[18]["r"].as_i64()), (Some(0), Some(0)));
    }
}
